  root = find(parent[x])
  diff[x] += diff[parent[x]]
  parent[x] = root
  return root

union(a, b, d):  // weight[a] - weight[b] = d
  ra = find(a), rb = find(b)
  if ra == rb: skip (consistent or not, but problem says results are consistent)
  // diff[a] = weight[a] - weight[ra]
  // diff[b] = weight[b] - weight[rb]
  // weight[a] - weight[b] = d
  // => weight[ra] + diff[a] - weight[rb] - diff[b] = d
  // => weight[ra] - weight[rb] = d - diff[a] + diff[b]
  // set diff[ra] = d - diff[a] + diff[b], parent[ra] = rb

query(a, b):
  ra = find(a), rb = find(b)
  if ra != rb: "UNKNOWN"
  else: diff[a] - diff[b]  // weight[a] - weight[b]

#include <bits/stdc++.h>
using namespace std;

struct WeightedDSU {
    vector<int> parent, sz;
    vector<long long> diff; 
    // diff[x] = weight[x] - weight[parent[x]]

    WeightedDSU(int n = 0) { init(n); }

    void init(int n) {
        parent.resize(n + 1);
        sz.assign(n + 1, 1);
        diff.assign(n + 1, 0);
        for (int i = 0; i <= n; ++i) parent[i] = i;
    }

    int find(int x) {
        if (parent[x] == x) return x;
        int p = parent[x];
        parent[x] = find(parent[x]);
        diff[x] += diff[p];
        return parent[x];
    }

    long long weight(int x) {
        find(x);
        return diff[x]; // weight[x] - weight[root]
    }

    bool unite(int a, int b, long long w) {
        // given: weight[a] - weight[b] = w
        int ra = find(a), rb = find(b);
        long long wa = weight(a);
        long long wb = weight(b);

        if (ra == rb) return (wa - wb == w);

        if (sz[ra] < sz[rb]) {
            // attach ra under rb
            parent[ra] = rb;
            diff[ra] = w + wb - wa; // weight[ra] - weight[rb]
            sz[rb] += sz[ra];
        } else {
            // attach rb under ra
            parent[rb] = ra;
            diff[rb] = wa - wb - w; // weight[rb] - weight[ra]
            sz[ra] += sz[rb];
        }
        return true;
    }

    bool same(int a, int b) {
        return find(a) == find(b);
    }

    long long difference(int a, int b) {
        // returns weight[a] - weight[b]
        return weight(a) - weight(b);
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m, q;
    while (cin >> n >> m >> q) {
        if (n == 0 && m == 0 && q == 0) break;

        WeightedDSU dsu(n);

        for (int i = 0; i < m; ++i) {
            int a, b;
            long long w;
            cin >> a >> b >> w;
            dsu.unite(a, b, w); // a is heavier than b by w
        }

        for (int i = 0; i < q; ++i) {
            int a, b;
            cin >> a >> b;
            if (!dsu.same(a, b)) {
                cout << "UNKNOWN\n";
            } else {
                cout << dsu.difference(a, b) << "\n";
            }
        }
    }

    return 0;
}

