#define MAXN 100005
#define MAXQ 100005

typedef struct {
    int to;
    int next;
    long long weight; // difference: to - from = weight
} Edge;

Edge edges[MAXN * 2];
int head[MAXN];
int edge_cnt;

long long dist[MAXN];
int visited[MAXN];

void add_edge(int u, int v, long long w) {
    edges[edge_cnt].to = v;
    edges[edge_cnt].weight = w;
    edges[edge_cnt].next = head[u];
    head[u] = edge_cnt++;

    edges[edge_cnt].to = u;
    edges[edge_cnt].weight = -w;
    edges[edge_cnt].next = head[v];
    head[v] = edge_cnt++;
}

int dfs(int u, int parent) {
    visited[u] = 1;
    for (int i = head[u]; i != -1; i = edges[i].next) {
        int v = edges[i].to;
        long long w = edges[i].weight;
        if (v == parent) continue;
        if (!visited[v]) {
            dist[v] = dist[u] + w;
            if (!dfs(v, u)) return 0;
        } else {
            // Check consistency: dist[v] should equal dist[u] + w
            if (dist[v] != dist[u] + w) return 0;
        }
    }
    return 1;
}

int main() {
    int n, q;
    while (scanf("%d %d", &n, &q) == 2) {
        if (n == 0 && q == 0) break;

        // Initialize
        memset(head, -1, sizeof(int) * (n + 1));
        memset(visited, 0, sizeof(int) * (n + 1));
        memset(dist, 0, sizeof(long long) * (n + 1));
        edge_cnt = 0;

        // Read measurement results
        for (int i = 0; i < q; i++) {
            char type[2];
            scanf("%s", type);
            if (type[0] == '!') {
                int a, b;
                long long w;
                scanf("%d %d %lld", &a, &b, &w);
                add_edge(a, b, w);
            } else { // type == '?'
                int a, b;
                scanf("%d %d", &a, &b);
                // Check if both are in the same connected component
                if (!visited[a]) dfs(a, -1);
                if (!visited[b]) dfs(b, -1);

                // If they are in the same component, answer is dist[b] - dist[a]
                // But we need to check if they are connected via the graph
                // We can do a quick DFS from a to see if b is reachable
                // Reset visited for this check? Actually we already have dist computed.
                // Better: run a small DFS from a limited to component
                // Simpler: just check if dist[b] is set and if they are in same component
                // We'll do a separate check using visited markers for component
                // Since we used visited for overall, we need component id
                // Let's use a separate array for component id
                // For simplicity, we'll just do a fresh DFS from a to see if b reachable
                int comp_visited[MAXN] = {0};
                int stack[MAXN];
                int top = 0;
                stack[top++] = a;
                comp_visited[a] = 1;
                int found = 0;
                while (top > 0 && !found) {
                    int u = stack[--top];
                    for (int j = head[u]; j != -1; j = edges[j].next) {
                        int v = edges[j].to;
                        if (!comp_visited[v]) {
                            comp_visited[v] = 1;
                            stack[top++] = v;
                            if (v == b) {
                                found = 1;
                                break;
                            }
                        }
                    }
                }
                if (found) {
                    printf("%lld\n", dist[b] - dist[a]);
                } else {
                    printf("UNKNOWN\n");
                }
            }
        }
    }
    return 0;
}

