#include <stdio.h>
#include <stdlib.h>

typedef long long ll;

typedef struct {
    int to;
    ll w;      // weight[to] - weight[from]
    int next;
} Edge;

static void add_edge(Edge *edges, int *head, int *ecnt, int u, int v, ll w) {
    edges[*ecnt].to = v;
    edges[*ecnt].w = w;
    edges[*ecnt].next = head[u];
    head[u] = (*ecnt)++;
}

int main(void) {
    int n, m, q;

    while (scanf("%d %d %d", &n, &m, &q) == 3) {
        if (n == 0 && m == 0 && q == 0) break;

        int maxEdges = 2 * m + 5;
        Edge *edges = (Edge *)malloc(sizeof(Edge) * maxEdges);
        int *head = (int *)malloc(sizeof(int) * (n + 1));
        int *comp = (int *)malloc(sizeof(int) * (n + 1));
        ll *dist = (ll *)malloc(sizeof(ll) * (n + 1));
        int *queue = (int *)malloc(sizeof(int) * (n + 5));

        for (int i = 1; i <= n; i++) head[i] = -1;
        int ecnt = 0;

        for (int i = 0; i < m; i++) {
            int a, b;
            ll d;
            scanf("%d %d %lld", &a, &b, &d);
            // a is heavier than b by d: weight[a] - weight[b] = d
            // So weight[b] = weight[a] - d  => weight[b] - weight[a] = -d
            add_edge(edges, head, &ecnt, a, b, -d);
            add_edge(edges, head, &ecnt, b, a, d);
        }

        for (int i = 1; i <= n; i++) comp[i] = -1;

        int cid = 0;
        for (int s = 1; s <= n; s++) {
            if (comp[s] != -1) continue;

            int front = 0, back = 0;
            queue[back++] = s;
            comp[s] = cid;
            dist[s] = 0;

            while (front < back) {
                int u = queue[front++];
                for (int e = head[u]; e != -1; e = edges[e].next) {
                    int v = edges[e].to;
                    ll w = edges[e].w;
                    if (comp[v] == -1) {
                        comp[v] = cid;
                        dist[v] = dist[u] + w;
                        queue[back++] = v;
                    }
                }
            }
            cid++;
        }

        for (int i = 0; i < q; i++) {
            int x, y;
            scanf("%d %d", &x, &y);
            if (comp[x] == -1 || comp[y] == -1 || comp[x] != comp[y]) {
                printf("UNKNOWN\n");
            } else {
                // dist[v] = weight[v] - weight[root]
                // so weight[y] - weight[x] = dist[y] - dist[x]
                printf("%lld\n", dist[y] - dist[x]);
            }
        }

        free(edges);
        free(head);
        free(comp);
        free(dist);
        free(queue);
    }

    return 0;
}

