public class Main {
    static int[] parent;
    static long[] diff; // diff[i] = weight[i] - weight[parent[i]]

    // Find with path compression, updating diff
    static int find(int x) {
        if (parent[x] != x) {
            int origParent = parent[x];
            parent[x] = find(parent[x]);
            diff[x] += diff[origParent];
        }
        return parent[x];
    }

    // Union: weight[a] - weight[b] = w
    static boolean union(int a, int b, long w) {
        int ra = find(a);
        int rb = find(b);
        if (ra == rb) {
            // Check consistency: diff[a] - diff[b] should equal w
            return diff[a] - diff[b] == w;
        }
        // Attach ra under rb
        // We want: diff[a] - diff[b] = w
        // After union, we set parent[ra] = rb, and diff[ra] accordingly
        // diff[a] = weight[a] - weight[ra]
        // diff[b] = weight[b] - weight[rb]
        // We want: (diff[a] + diff[ra]) - diff[b] = w
        // => diff[ra] = w + diff[b] - diff[a]
        parent[ra] = rb;
        diff[ra] = w + diff[b] - diff[a];
        return true;
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringBuilder sb = new StringBuilder();
        String line;

        while ((line = br.readLine()) != null) {
            line = line.trim();
            if (line.isEmpty()) continue;
            String[] parts = line.split("\\s+");
            int n = Integer.parseInt(parts[0]);
            int m = Integer.parseInt(parts[1]);
            if (n == 0 && m == 0) break;

            parent = new int[n];
            diff = new long[n];
            for (int i = 0; i < n; i++) {
                parent[i] = i;
                diff[i] = 0;
            }

            for (int i = 0; i < m; i++) {
                line = br.readLine().trim();
                while (line.isEmpty()) line = br.readLine().trim();
                parts = line.split("\\s+");
                char type = parts[0].charAt(0);
                if (type == '!') {
                    int a = Integer.parseInt(parts[1]) - 1;
                    int b = Integer.parseInt(parts[2]) - 1;
                    int w = Integer.parseInt(parts[3]);
                    union(a, b, w);
                } else { // '?'
                    int a = Integer.parseInt(parts[1]) - 1;
                    int b = Integer.parseInt(parts[2]) - 1;
                    if (find(a) != find(b)) {
                        sb.append("UNKNOWN\n");
                    } else {
                        long ans = diff[a] - diff[b];
                        sb.append(ans).append("\n");
                    }
                }
            }
        }
        System.out.print(sb.toString());
    }
}

