public class Main {
    static int[] parent;
    static long[] diff; // diff[i] = weight[i] - weight[parent[i]]

    static int find(int x) {
        if (parent[x] == x) return x;
        int root = find(parent[x]);
        diff[x] += diff[parent[x]];
        parent[x] = root;
        return root;
    }

    static long getDiff(int x) {
        find(x);
        return diff[x];
    }

    static void union(int a, int b, long d) {
        // weight[a] - weight[b] = d
        long da = getDiff(a); // weight[a] - weight[root_a]
        long db = getDiff(b); // weight[b] - weight[root_b]
        int ra = find(a);
        int rb = find(b);
        if (ra == rb) return;
        // weight[a] = da + weight[ra]
        // weight[b] = db + weight[rb]
        // weight[a] - weight[b] = d
        // da + weight[ra] - db - weight[rb] = d
        // weight[ra] - weight[rb] = d - da + db
        // diff[ra] should be weight[ra] - weight[rb] = d - da + db
        parent[ra] = rb;
        diff[ra] = d - da + db;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        while (sc.hasNextInt()) {
            int n = sc.nextInt();
            int m = sc.nextInt();
            if (n == 0 && m == 0) break;

            parent = new int[n + 1];
            diff = new long[n + 1];
            for (int i = 0; i <= n; i++) {
                parent[i] = i;
                diff[i] = 0;
            }

            for (int i = 0; i < m; i++) {
                String type = sc.next();
                int a = sc.nextInt();
                int b = sc.nextInt();
                if (type.equals("!")) {
                    long d = sc.nextLong();
                    // a is heavier than b by d: weight[a] - weight[b] = d
                    union(a, b, d);
                } else {
                    // query
                    int ra = find(a);
                    int rb = find(b);
                    if (ra != rb) {
                        System.out.println("UNKNOWN");
                    } else {
                        long da = getDiff(a);
                        long db = getDiff(b);
                        System.out.println(Math.abs(da - db));
                    }
                }
            }
        }
    }
}

import java.io.*;
import java.util.*;

public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        String next() throws IOException {
            StringBuilder sb = new StringBuilder();
            int c;
            do {
                c = read();
                if (c == -1) return null;
            } while (c <= ' ');
            while (c > ' ') {
                sb.append((char) c);
                c = read();
            }
            return sb.toString();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }

    static class WeightedDSU {
        int[] parent;
        int[] rank;
        long[] diff; // diff[x] = weight[x] - weight[parent[x]]

        WeightedDSU(int n) {
            parent = new int[n + 1];
            rank = new int[n + 1];
            diff = new long[n + 1];
            for (int i = 1; i <= n; i++) {
                parent[i] = i;
            }
        }

        int find(int x) {
            if (parent[x] == x) return x;
            int p = parent[x];
            int r = find(p);
            diff[x] += diff[p];
            return parent[x] = r;
        }

        long weightToRoot(int x) {
            find(x);
            return diff[x];
        }

        boolean same(int x, int y) {
            return find(x) == find(y);
        }

        // impose: weight[x] - weight[y] = w
        void union(int x, int y, long w) {
            int rx = find(x);
            int ry = find(y);
            long wx = diff[x];
            long wy = diff[y];

            if (rx == ry) return;

            // Need: after merge, weight[x] - weight[y] = w
            // If attach rx under ry:
            // (wx + d) - wy = w  => d = w - wx + wy
            long d = w - wx + wy;

            if (rank[rx] < rank[ry]) {
                parent[rx] = ry;
                diff[rx] = d;
            } else {
                // attach ry under rx
                // Need diff[ry] = weight[ry] - weight[rx]
                parent[ry] = rx;
                diff[ry] = -d;
                if (rank[rx] == rank[ry]) rank[rx]++;
            }
        }

        // returns weight[x] - weight[y]
        long difference(int x, int y) {
            return weightToRoot(x) - weightToRoot(y);
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();
        StringBuilder out = new StringBuilder();

        while (true) {
            String first = fs.next();
            if (first == null) break;
            int n = Integer.parseInt(first);
            int m = fs.nextInt();
            if (n == 0 && m == 0) break;

            WeightedDSU dsu = new WeightedDSU(n);

            for (int i = 0; i < m; i++) {
                String type = fs.next();
                int a = fs.nextInt();
                int b = fs.nextInt();
                if (type.equals("!")) {
                    long w = Long.parseLong(fs.next());
                    // a is heavier than b by w => weight[a] - weight[b] = w
                    dsu.union(a, b, w);
                } else { // "?"
                    if (!dsu.same(a, b)) {
                        out.append("UNKNOWN\n");
                    } else {
                        out.append(dsu.difference(a, b)).append('\n');
                    }
                }
            }
        }

        System.out.print(out.toString());
    }
}
